package com.portfolio.orderservice.domain; import jakarta.persistence.*; import java.math.BigDecimal; @Entity public class CustomerOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long productId; private Integer quantity; private String customerEmail; private String status="RECEIVED"; public Long getId(){return id;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public String getCustomerEmail(){return customerEmail;} public void setCustomerEmail(String v){customerEmail=v;} public String getStatus(){return status;} }